const body = $json.body ?? $json;

const question =
  typeof body.question === 'string'
    ? body.question.trim()
    : '';

const requestType =
  typeof body.requestType === 'string'
    ? body.requestType.trim()
    : '';

const logText =
  typeof body.logText === 'string'
    ? body.logText.trim()
    : '';

const sessionId =
  typeof body.sessionId === 'string' &&
  body.sessionId.trim()
    ? body.sessionId.trim()
    : 'local-demo-session';

const startedAt = Date.now();

if (!question) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        success: false,
        error: 'INVALID_QUESTION',
        message: '질문을 입력하세요.',
        requestType: requestType || null,
        question: '',
        logText,
        sessionId,
        startedAt,
      },
    },
  ];
}

if (
  requestType !== 'operation' &&
  requestType !== 'diagnosis'
) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        success: false,
        error: 'INVALID_REQUEST_TYPE',
        message:
          'requestType은 operation 또는 diagnosis여야 합니다.',
        requestType: requestType || null,
        question,
        logText,
        sessionId,
        startedAt,
      },
    },
  ];
}

return [
  {
    json: {
      valid: true,
      statusCode: 200,
      question,
      requestType,
      logText,
      sessionId,
      startedAt,
    },
  },
];

const items = $input.all();

const originalRequest =
  $('요청 검증').first().json;

const question =
  originalRequest.question ?? '';

const requestType =
  originalRequest.requestType ?? 'operation';

const logText =
  originalRequest.logText ?? '';

const sessionId =
  originalRequest.sessionId ?? 'local-demo-session';

const startedAt =
  originalRequest.startedAt ?? Date.now();

const documents = items
  .map((item, index) => {
    const json = item.json ?? {};

    const document =
      json.document ?? {};

    const metadata =
      document.metadata ?? {};

    const pageContent =
      typeof document.pageContent === 'string'
        ? document.pageContent.trim()
        : '';

    const score =
      typeof json.score === 'number'
        ? json.score
        : null;

    return {
      rank: index + 1,
      score,
      pageContent,

      documentName:
        metadata.documentName ?? '',

      title:
        metadata.title ?? '',

      category:
        metadata.category ?? '',

      section:
        metadata.section ?? '',

      chunkId:
        metadata.chunkId ?? '',

      source:
        metadata.source ?? '',
    };
  })
  .filter((doc) => doc.pageContent);

const context = documents
  .map((doc) => {
    return [
      `[검색 결과 ${doc.rank}]`,
      `문서명: ${doc.documentName}`,
      `제목: ${doc.title}`,
      `카테고리: ${doc.category}`,
      `섹션: ${doc.section}`,
      `청크 ID: ${doc.chunkId}`,
      `유사도: ${
        doc.score !== null
          ? doc.score.toFixed(4)
          : 'N/A'
      }`,
      '',
      doc.pageContent,
    ].join('\n');
  })
  .join('\n\n--------------------\n\n');

const sources = documents.map((doc) => ({
  documentName: doc.documentName,
  category: doc.category,
  section: doc.section,
  chunkId: doc.chunkId,
}));

return [
  {
    json: {
      question,
      requestType,
      logText,
      sessionId,
      startedAt,

      searchResultCount:
        documents.length,

      context,

      sources,

      retrievedDocuments:
        documents,
    },
  },
];

const llmOutput = $json.text ?? '';

const requestData =
  $('운영 검색 결과 정리').first().json;

const startedAt =
  requestData.startedAt ?? Date.now();

const sources =
  Array.isArray(requestData.sources)
    ? requestData.sources
    : [];

const answer =
  typeof llmOutput === 'string'
    ? llmOutput.trim()
    : '';

const abstainMessage =
  '제공된 내부 자료에서는 확인할 수 없습니다.';

const isAbstained =
  answer === abstainMessage;

return [
  {
    json: {
      success: true,
      requestType: 'operation',

      answer:
        answer || abstainMessage,

      diagnosis: null,

      sources:
        isAbstained
          ? []
          : sources,

      responseTimeMs:
        Date.now() - startedAt,
    },
  },
];

const items = $input.all();

const originalRequest =
  $('요청 검증').first().json;

const question =
  originalRequest.question ?? '';

const requestType =
  originalRequest.requestType ?? 'diagnosis';

const logText =
  originalRequest.logText ?? '';

const sessionId =
  originalRequest.sessionId ?? 'local-demo-session';

const startedAt =
  originalRequest.startedAt ?? Date.now();

const documents = items
  .map((item, index) => {
    const json = item.json ?? {};

    const document =
      json.document ?? {};

    const metadata =
      document.metadata ?? {};

    const pageContent =
      typeof document.pageContent === 'string'
        ? document.pageContent.trim()
        : '';

    const score =
      typeof json.score === 'number'
        ? json.score
        : null;

    return {
      rank: index + 1,
      score,
      pageContent,

      documentName:
        metadata.documentName ?? '',

      title:
        metadata.title ?? '',

      category:
        metadata.category ?? '',

      section:
        metadata.section ?? '',

      chunkId:
        metadata.chunkId ?? '',

      source:
        metadata.source ?? '',
    };
  })
  .filter((doc) => doc.pageContent);

const context = documents
  .map((doc) => {
    return [
      `[검색 결과 ${doc.rank}]`,
      `문서명: ${doc.documentName}`,
      `제목: ${doc.title}`,
      `카테고리: ${doc.category}`,
      `섹션: ${doc.section}`,
      `청크 ID: ${doc.chunkId}`,
      `유사도: ${
        doc.score !== null
          ? doc.score.toFixed(4)
          : 'N/A'
      }`,
      '',
      doc.pageContent,
    ].join('\n');
  })
  .join('\n\n--------------------\n\n');

const sources = documents.map((doc) => ({
  documentName: doc.documentName,
  category: doc.category,
  section: doc.section,
  chunkId: doc.chunkId,
}));

return [
  {
    json: {
      question,
      requestType,
      logText,
      sessionId,
      startedAt,

      searchResultCount:
        documents.length,

      context,

      sources,

      retrievedDocuments:
        documents,
    },
  },
];

const llmText =
  typeof $json.text === 'string'
    ? $json.text.trim()
    : '';

const requestData =
  $('장애 검색 결과 정리').first().json;

const startedAt =
  requestData.startedAt ?? Date.now();

const sources =
  Array.isArray(requestData.sources)
    ? requestData.sources
    : [];

const abstainMessage =
  '제공된 내부 자료에서는 확인할 수 없습니다.';

const finalText =
  llmText || abstainMessage;

const isAbstained =
  finalText === abstainMessage;

/*
 * S=...;C=...;K=...;A=...
 * 형태의 값을 추출한다.
 */
function getValue(text, key) {
  const pattern =
    new RegExp(
      `(?:^|;)${key}=([^;]*)`,
    );

  const match =
    text.match(pattern);

  if (!match) {
    return '';
  }

  return match[1].trim();
}

/*
 * "|" 기준으로 최대 2개 항목을 배열로 만든다.
 */
function parseList(value) {
  if (!value) {
    return [];
  }

  return value
    .split('|')
    .map((item) =>
      item.trim(),
    )
    .filter((item) =>
      item &&
      item !== '없음',
    )
    .slice(0, 2);
}

const summary =
  getValue(
    finalText,
    'S',
  );

const possibleCauses =
  parseList(
    getValue(
      finalText,
      'C',
    ),
  );

const checkSteps =
  parseList(
    getValue(
      finalText,
      'K',
    ),
  );

const actions =
  parseList(
    getValue(
      finalText,
      'A',
    ),
  );

const diagnosis =
  isAbstained
    ? null
    : {
        summary:
          summary || finalText,

        possibleCauses,

        checkSteps,

        actions,
      };

/*
 * 사람이 읽기 좋은 answer 생성
 */
let answer =
  finalText;

if (
  !isAbstained &&
  summary
) {
  const parts = [
    `요약: ${summary}`,
  ];

  if (
    possibleCauses.length > 0
  ) {
    parts.push(
      '',
      '가능한 원인:',
      ...possibleCauses.map(
        (item) =>
          `- ${item}`,
      ),
    );
  }

  if (
    checkSteps.length > 0
  ) {
    parts.push(
      '',
      '점검 순서:',
      ...checkSteps.map(
        (item, index) =>
          `${index + 1}. ${item}`,
      ),
    );
  }

  if (
    actions.length > 0
  ) {
    parts.push(
      '',
      '조치 방법:',
      ...actions.map(
        (item, index) =>
          `${index + 1}. ${item}`,
      ),
    );
  }

  answer =
    parts.join('\n');
}

/*
 * 출처 중복 제거
 */
const uniqueSources = [];

const sourceKeys =
  new Set();

for (
  const source
  of sources
) {
  const key = [
    source.documentName ?? '',
    source.section ?? '',
    source.chunkId ?? '',
  ].join('|');

  if (
    sourceKeys.has(key)
  ) {
    continue;
  }

  sourceKeys.add(key);

  uniqueSources.push({
    documentName:
      source.documentName ?? '',

    category:
      source.category ?? '',

    section:
      source.section ?? '',

    chunkId:
      source.chunkId ?? '',
  });
}

/*
 * 최종 Webhook 응답
 */
return [
  {
    json: {
      success: true,

      requestType:
        'diagnosis',

      answer:
        isAbstained
          ? abstainMessage
          : answer,

      diagnosis,

      sources:
        isAbstained
          ? []
          : uniqueSources,

      responseTimeMs:
        Date.now() -
        startedAt,
    },
  },
];
